# Check for requests import
found_requests = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'requests' for name in node.names):
        found_requests = True
    if isinstance(node, ast.ImportFrom) and node.module == 'requests':
        found_requests = True

if not found_requests:
    raise AssertionError('Task 1: Missing import requests')

# Check that custom_headers dictionary exists with User-Agent key
found_headers_dict = False
found_user_agent = False
for node in ast.walk(tree):
    if isinstance(node, ast.Dict):
        found_headers_dict = True
        # Check keys for 'User-Agent'
        for key in node.keys:
            if isinstance(key, ast.Constant) and key.value == 'User-Agent':
                found_user_agent = True
            elif isinstance(key, ast.Str) and key.s == 'User-Agent':  # Older Python
                found_user_agent = True

if not found_headers_dict:
    raise AssertionError('custom_headers dictionary not found or malformed')
if not found_user_agent:
    raise AssertionError('custom_headers missing "User-Agent" key')

# Check for requests.get() call with headers parameter
found_get = False
correct_url = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == 'requests' and node.func.attr == 'get':
                # Check for headers keyword argument
                for kw in node.keywords:
                    if kw.arg == 'headers':
                        found_get = True
                        # Check that headers argument references custom_headers
                        if isinstance(kw.value, ast.Name) and kw.value.id == 'custom_headers':
                            pass  # Good, using the correct variable
                # Check URL is correct (positional first argument)
                if node.args:
                    url_arg = ast.unparse(node.args[0])
                    if 'httpbin.org/get' in url_arg:
                        correct_url = True

if not found_get:
    raise AssertionError('Task 3: Missing requests.get() call with headers= parameter')
if not correct_url:
    raise AssertionError('Task 3: URL should be "http://httpbin.org/get"')

